      "hi": "50 किग्रा द्रव्यमान की एक लड़की 25 सेकंड में 5 मीटर की ऊंचाई तक रस्सी पर चढ़ती है। व्यय की गई शक्ति कितनी है? (g = 9.8 m/s² लें)"
